import nodeTest, {
  describe,
  it,
  before,
  after,
  beforeEach,
  afterEach
} from 'node:test';
import assert from 'node:assert/strict';

export { describe, it, beforeEach, afterEach };
export const test = it;
export const beforeAll = before;
export const afterAll = after;

function deepMatchesObject(actual, expected) {
  if (expected === actual) return true;
  if (expected === null || actual === null || typeof expected !== 'object' || typeof actual !== 'object') {
    return Object.is(actual, expected);
  }
  if (Array.isArray(expected)) {
    if (!Array.isArray(actual) || actual.length !== expected.length) return false;
    return expected.every((item, i) => deepMatchesObject(actual[i], item));
  }
  for (const key of Object.keys(expected)) {
    if (!Object.prototype.hasOwnProperty.call(actual, key)) return false;
    if (!deepMatchesObject(actual[key], expected[key])) return false;
  }
  return true;
}

function makeMatchers(actual, negated = false) {
  const check = (cond, msg) => {
    if (negated ? cond : !cond) {
      assert.fail(msg);
    }
  };

  return {
    get not() {
      return makeMatchers(actual, !negated);
    },
    toBe(expected) {
      if (negated) assert.notStrictEqual(actual, expected);
      else assert.strictEqual(actual, expected);
    },
    toEqual(expected) {
      if (negated) assert.notDeepStrictEqual(actual, expected);
      else assert.deepStrictEqual(actual, expected);
    },
    toStrictEqual(expected) {
      if (negated) assert.notDeepStrictEqual(actual, expected);
      else assert.deepStrictEqual(actual, expected);
    },
    toBeNull() {
      check(actual === null, `Expected ${String(actual)} ${negated ? 'not ' : ''}to be null`);
    },
    toBeUndefined() {
      check(actual === undefined, `Expected ${String(actual)} ${negated ? 'not ' : ''}to be undefined`);
    },
    toBeDefined() {
      check(actual !== undefined, `Expected value ${negated ? 'not ' : ''}to be defined`);
    },
    toBeTruthy() {
      check(Boolean(actual), `Expected ${String(actual)} ${negated ? 'not ' : ''}to be truthy`);
    },
    toBeFalsy() {
      check(!actual, `Expected ${String(actual)} ${negated ? 'not ' : ''}to be falsy`);
    },
    toBeGreaterThan(n) {
      check(actual > n, `Expected ${actual} ${negated ? 'not ' : ''}to be > ${n}`);
    },
    toBeGreaterThanOrEqual(n) {
      check(actual >= n, `Expected ${actual} ${negated ? 'not ' : ''}to be >= ${n}`);
    },
    toBeLessThan(n) {
      check(actual < n, `Expected ${actual} ${negated ? 'not ' : ''}to be < ${n}`);
    },
    toBeLessThanOrEqual(n) {
      check(actual <= n, `Expected ${actual} ${negated ? 'not ' : ''}to be <= ${n}`);
    },
    toHaveLength(len) {
      check(actual?.length === len, `Expected length ${actual?.length} ${negated ? 'not ' : ''}to be ${len}`);
    },
    toContain(item) {
      const has = typeof actual === 'string'
        ? actual.includes(String(item))
        : Array.isArray(actual)
          ? actual.includes(item)
          : false;
      check(has, `Expected ${JSON.stringify(actual)} ${negated ? 'not ' : ''}to contain ${JSON.stringify(item)}`);
    },
    toContainEqual(item) {
      const has = Array.isArray(actual) && actual.some((el) => {
        try {
          assert.deepStrictEqual(el, item);
          return true;
        } catch {
          return false;
        }
      });
      check(has, `Expected array ${negated ? 'not ' : ''}to contain equal ${JSON.stringify(item)}`);
    },
    toMatch(pattern) {
      const re = typeof pattern === 'string' ? new RegExp(pattern) : pattern;
      check(re.test(String(actual)), `Expected ${String(actual)} ${negated ? 'not ' : ''}to match ${String(pattern)}`);
    },
    toMatchObject(expected) {
      check(deepMatchesObject(actual, expected), `Expected ${JSON.stringify(actual)} ${negated ? 'not ' : ''}to match object ${JSON.stringify(expected)}`);
    },
    toHaveProperty(keyPath, value) {
      const parts = String(keyPath).split('.');
      let cur = actual;
      let exists = true;
      for (const p of parts) {
        if (cur !== null && cur !== undefined && p in Object(cur)) {
          cur = cur[p];
        } else {
          exists = false;
          break;
        }
      }
      if (arguments.length >= 2) {
        let eq = exists;
        if (eq) {
          try { assert.deepStrictEqual(cur, value); } catch { eq = false; }
        }
        check(eq, `Expected property ${keyPath} ${negated ? 'not ' : ''}to equal ${JSON.stringify(value)}`);
      } else {
        check(exists, `Expected property ${keyPath} ${negated ? 'not ' : ''}to exist`);
      }
    },
    toThrow(expected) {
      let threw = false;
      let err;
      try {
        actual();
      } catch (e) {
        threw = true;
        err = e;
      }
      if (negated) {
        check(threw, 'Expected function not to throw');
      } else {
        check(threw, 'Expected function to throw');
        if (expected instanceof RegExp) {
          assert.match(String(err?.message ?? err), expected);
        } else if (typeof expected === 'string') {
          assert.ok(String(err?.message ?? err).includes(expected));
        }
      }
    },
    toHaveBeenCalled() {
      check((actual?.mock?.calls?.length ?? 0) > 0, 'Expected mock to have been called');
    },
    toHaveBeenCalledTimes(count) {
      check((actual?.mock?.calls?.length ?? 0) === count, `Expected mock calls ${actual?.mock?.calls?.length ?? 0} to be ${count}`);
    },
    toHaveBeenCalledWith(...expectedArgs) {
      const calls = actual?.mock?.calls ?? [];
      const found = calls.some((c) => {
        try {
          assert.deepStrictEqual(c, expectedArgs);
          return true;
        } catch {
          return false;
        }
      });
      check(found, `Expected mock to have been called with ${JSON.stringify(expectedArgs)}`);
    }
  };
}

export function expect(actual) {
  const base = makeMatchers(actual, false);
  const makePromiseMatchers = (negated) =>
    new Proxy(
      {},
      {
        get(_t, prop) {
          if (prop === 'not') {
            return makePromiseMatchers(!negated);
          }
          return async (...args) => {
            const val = await actual;
            return makeMatchers(val, negated)[prop](...args);
          };
        },
      },
    );

  const makeRejectsMatchers = (negated) =>
    new Proxy(
      {},
      {
        get(_t, prop) {
          if (prop === 'not') {
            return makeRejectsMatchers(!negated);
          }
          if (prop === 'toThrow') {
            return async (expected) => {
              let err;
              let rejected = false;
              try {
                await actual;
              } catch (e) {
                rejected = true;
                err = e;
              }
              if (negated) {
                assert.ok(!rejected, `Expected promise not to reject, rejected with ${String(err)}`);
                return;
              }
              assert.ok(rejected, 'Expected promise to reject');
              if (expected instanceof RegExp) {
                assert.match(String(err?.message ?? err), expected);
              } else if (typeof expected === 'string') {
                assert.ok(String(err?.message ?? err).includes(expected));
              }
            };
          }
          return async (...args) => {
            let err;
            let rejected = false;
            try {
              await actual;
            } catch (e) {
              rejected = true;
              err = e;
            }
            assert.ok(rejected, 'Expected promise to reject');
            return makeMatchers(err, negated)[prop](...args);
          };
        },
      },
    );

  return {
    ...base,
    resolves: makePromiseMatchers(false),
    rejects: makeRejectsMatchers(false),
  };
}

export const vi = {
  fn(impl) {
    const calls = [];
    const fn = (...args) => {
      calls.push(args);
      return impl ? impl(...args) : undefined;
    };
    fn.mock = { calls };
    fn.mockImplementation = (next) => {
      impl = next;
      return fn;
    };
    fn.mockReturnValue = (val) => {
      impl = () => val;
      return fn;
    };
    fn.mockResolvedValue = (val) => {
      impl = async () => val;
      return fn;
    };
    fn.mockClear = () => {
      calls.length = 0;
    };
    return fn;
  }
};
